  measureText: (s) => ({ width: String(s).length * 8 }),
  createLinearGradient: (...a) => { checkNum('grad', a); return { addColorStop() {} }; },
  fillText: (s, x, y) => { texts.push(String(s)); checkNum('fillText', [x, y]); },
  strokeText: (s, x, y) => checkNum('strokeText', [x, y]),
};
const ctx2d = new Proxy(target, {
  get(t, k) { return k in t ? t[k] : (...args) => checkNum(String(k), args); },
  set(t, k, v) { if (typeof v === 'number' && !Number.isFinite(v)) bad.push('set ' + String(k)); t[k] = v; return true; },
});
const canvas = { width: 300, height: 150, style: {}, getContext: () => ctx2d,
  getBoundingClientRect: () => ({ left: 0, top: 0, width: 800, height: 600 }), addEventListener: (t, f) => canL.add(t, f) };
const store = {};
let toneCount = 0;
class P { setValueAtTime() {} exponentialRampToValueAtTime(v) { if (!(v > 0)) throw new Error('bad ramp ' + v); } }
class N { constructor() { this.frequency = new P(); this.gain = new P(); } connect(n) { return n; } start() {} stop() {} }
class AC { constructor() { this.state = 'running'; this.currentTime = 0; this.destination = {}; } createOscillator() { toneCount++; return new N(); } createGain() { return new N(); } resume() { return Promise.resolve(); } }
let rafCb = null;
