  var __v = []; var __orig = stepBall;
  stepBall = function (h) {
    const res = __orig(h);
    if (state === 'playing') {
      const r = ball.r, e = 1e-6;
      if (ball.x < r - e || ball.x > W - r + e) __v.push('x out ' + ball.x);
      if (ball.y < TOP + r - e) __v.push('above top ' + ball.y);
      for (const b of bricks) if (ball.x + r > b.x + e && ball.x - r < b.x + b.w - e && ball.y + r > b.y + e && ball.y - r < b.y + b.h - e) { __v.push('overlap ' + b.x + ',' + b.y + ' ball ' + ball.x + ',' + ball.y); break; }
