ok(G('state') === 'title', 'title state');
ok(texts.includes('BRICK BREAKER'), 'title drawn');
ok(G('bricks.length') === 72, 'level 1 has 72 bricks');
ok(texts.includes('SCORE') && texts.includes('LEVEL') && texts.includes('LIVES') && texts.includes('0') && texts.includes('1 / 2'), 'HUD drawn: ' + texts.join('|'));
ok(G('canvas.style.width') === '1002px' && G('canvas.style.height') === '751px', 'css size ' + G('canvas.style.width') + ' ' + G('canvas.style.height'));

