// Headless logic test for index.html: mocks DOM/canvas/audio, drives the real listeners and loop.
const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync(process.argv[2], 'utf8');
const code = html.match(/<script>([\s\S]*?)<\/script>/)[1];

function makeListeners() {
  const map = {};
  return {
    add(t, fn) { (map[t] = map[t] || []).push(fn); },
    fire(t, ev) { for (const fn of map[t] || []) fn(ev); },
  };
}
const winL = makeListeners(), docL = makeListeners(), canL = makeListeners();
const texts = [];
const bad = [];
function checkNum(name, args) {
  for (const a of args) if (typeof a === 'number' && !Number.isFinite(a)) bad.push(name + ':' + args.join(','));
}
const target = {
  measureText: (s) => ({ width: String(s).length * 8 }),
  createLinearGradient: (...a) => { checkNum('grad', a); return { addColorStop() {} }; },
  fillText: (s, x, y) => { texts.push(String(s)); checkNum('fillText', [x, y]); },
  strokeText: (s, x, y) => checkNum('strokeText', [x, y]),
};
const ctx2d = new Proxy(target, {
  get(t, k) { return k in t ? t[k] : (...args) => checkNum(String(k), args); },
  set(t, k, v) { if (typeof v === 'number' && !Number.isFinite(v)) bad.push('set ' + String(k)); t[k] = v; return true; },
});
const canvas = {
  width: 300, height: 150, style: {}, getContext: () => ctx2d,
  getBoundingClientRect: () => ({ left: 0, top: 0, width: 800, height: 600 }),
  addEventListener: (t, f) => canL.add(t, f),
};
const store = {};
let toneCount = 0;
class Param { setValueAtTime() {} exponentialRampToValueAtTime(v) { if (!(v > 0)) throw new Error('bad ramp ' + v); } }
class Node { constructor() { this.frequency = new Param(); this.gain = new Param(); } connect(n) { return n; } start() {} stop() {} }
class FakeAudio {
  constructor() { this.state = 'running'; this.currentTime = 0; this.destination = {}; }
  createOscillator() { toneCount++; return new Node(); }
  createGain() { return new Node(); }
  resume() { return Promise.resolve(); }
}
let rafCb = null;
const sb = {
  document: { getElementById: () => canvas, addEventListener: (t, f) => docL.add(t, f), hidden: false },
  localStorage: { getItem: (k) => (k in store ? store[k] : null), setItem: (k, v) => { store[k] = String(v); } },
  requestAnimationFrame: (cb) => { rafCb = cb; return 1; },
  innerWidth: 1024, innerHeight: 768, devicePixelRatio: 1, AudioContext: FakeAudio,
  addEventListener: (t, f) => winL.add(t, f),
};
sb.window = sb;
vm.createContext(sb);
vm.runInContext(code, sb, { filename: 'game.js' });
const G = (e) => vm.runInContext(e, sb);
let now = 1000;
function tick(ms = 1000 / 60) { now += ms; const cb = rafCb; rafCb = null; texts.length = 0; cb(now); }
function key(type, code, extra = {}) {
  winL.fire(type, Object.assign({ code, repeat: false, ctrlKey: false, metaKey: false, altKey: false, preventDefault() {} }, extra));
}
function ptr(type, x, y, extra = {}) {
  const ev = Object.assign({ clientX: x, clientY: y, pointerType: 'mouse', button: 0 }, extra);
  (type === 'pointerdown' ? canL : winL).fire(type, ev);
}
let passed = 0;
function ok(c, msg) { if (!c) { console.log('FAIL:', msg); process.exitCode = 1; } else passed++; }

// Invariants checked after every physics sub-step.
vm.runInContext(`
  var __v = []; var __orig = stepBall;
  stepBall = function (h) {
    const res = __orig(h);
    if (state === 'playing') {
      const r = ball.r, e = 1e-6;
      if (ball.x < r - e || ball.x > W - r + e) __v.push('x out ' + ball.x);
      if (ball.y < TOP + r - e) __v.push('above top ' + ball.y);
      for (const b of bricks) {
        if (ball.x + r > b.x + e && ball.x - r < b.x + b.w - e && ball.y + r > b.y + e && ball.y - r < b.y + b.h - e) {
          __v.push('overlap ' + b.x + ',' + b.y + ' ball ' + ball.x + ',' + ball.y); break;
        }
      }
      const sp = Math.hypot(ball.vx, ball.vy);
      if (Math.abs(sp - ball.speed) > 1e-6 * ball.speed) __v.push('speed mismatch');
      if (Math.abs(ball.vy) < 0.45 * ball.speed) __v.push('too flat ' + ball.vy);
      if (ball.speed > LEVELS[level].maxSpeed + 1e-9) __v.push('too fast');
    }
    return res;
  };`, sb);

// --- title screen
tick(); tick();
ok(G('state') === 'title', 'title state');
ok(texts.includes('BRICK BREAKER'), 'title drawn');
ok(G('bricks.length') === 72, 'level 1 has 72 bricks');
ok(texts.includes('SCORE') && texts.includes('LEVEL') && texts.includes('LIVES') && texts.includes('0') && texts.includes('1 / 2'),
  'HUD drawn: ' + texts.join('|'));
ok(G('canvas.style.width') === '1002px' && G('canvas.style.height') === '751px',
  'css size ' + G('canvas.style.width') + ' ' + G('canvas.style.height'));

// --- keyboard: start, steer, launch
key('keydown', 'Space'); key('keyup', 'Space');
ok(G('state') === 'serve', 'serve after Space');
tick();
ok(texts.includes('LEVEL 1') && texts.includes('Click or press Space to launch'), 'serve overlay');
const px0 = G('paddle.x');
key('keydown', 'ArrowLeft'); for (let i = 0; i < 15; i++) tick(); key('keyup', 'ArrowLeft');
const px1 = G('paddle.x');
ok(px1 < px0 - 150, `paddle moved left ${px0} -> ${px1}`);
ok(Math.abs(G('ball.x') - (G('paddle.x') + G('paddle.w') / 2)) < 1e-9, 'ball rides paddle while serving');
key('keydown', 'KeyD'); for (let i = 0; i < 10; i++) tick(); key('keyup', 'KeyD');
ok(G('paddle.x') > px1 + 100, 'D moves right');
key('keydown', 'ArrowLeft'); for (let i = 0; i < 120; i++) tick(); key('keyup', 'ArrowLeft');
ok(G('paddle.x') === 0, 'paddle clamps at left wall');
key('keydown', 'KeyD', { ctrlKey: true }); tick(); key('keyup', 'KeyD');
ok(G('paddle.x') === 0, 'Ctrl+D ignored');
key('keydown', 'Space');
ok(G('state') === 'playing' && G('ball.vy') < 0, 'Space launches');
for (let i = 0; i < 10; i++) tick();
ok(G('ball.y') < G('PADDLE_Y') - 20, 'ball travels');

// --- pause / resume
key('keydown', 'KeyP');
ok(G('state') === 'paused', 'P pauses');
const bx = G('ball.x'), by = G('ball.y');
for (let i = 0; i < 30; i++) tick();
ok(G('ball.x') === bx && G('ball.y') === by, 'frozen while paused');
ok(texts.includes('PAUSED'), 'paused overlay');
key('keydown', 'Escape');
ok(G('state') === 'playing', 'Esc resumes');
key('keydown', 'KeyP', { repeat: true });
ok(G('state') === 'playing', 'key repeat ignored');
winL.fire('blur', {});
ok(G('state') === 'paused', 'blur pauses');
ptr('pointerdown', 400, 300);
ok(G('state') === 'playing', 'click resumes');
sb.document.hidden = true; docL.fire('visibilitychange', {}); sb.document.hidden = false;
ok(G('state') === 'paused', 'hidden tab pauses');
key('keydown', 'Enter');
ok(G('state') === 'playing', 'Enter resumes');

// --- HUD buttons
const sbx = G('BTN_SOUND.x') + 14, sby = G('BTN_SOUND.y') + 14, pbx = G('BTN_PAUSE.x') + 14, pby = G('BTN_PAUSE.y') + 14;
ptr('pointerdown', sbx, sby); ok(G('muted') === true, 'sound button mutes');
ptr('pointerdown', sbx, sby); ok(G('muted') === false, 'sound button unmutes');
key('keydown', 'KeyM'); ok(G('muted') === true, 'M mutes');
key('keydown', 'KeyM'); ok(G('muted') === false, 'M unmutes');
ptr('pointerdown', pbx, pby); ok(G('state') === 'paused', 'pause button pauses');
ptr('pointerdown', pbx, pby); ok(G('state') === 'playing', 'pause button resumes');
ptr('pointerdown', 400, 300, { button: 2 }); ok(G('state') === 'playing', 'right click ignored');

// --- mouse steering & keyboard takeover
ptr('pointermove', 100, 500); tick();
ok(Math.abs(G('paddle.x + paddle.w / 2') - 100) < 1e-9, 'paddle follows mouse');
key('keydown', 'ArrowRight'); tick(); tick(); key('keyup', 'ArrowRight');
const afterKey = G('paddle.x'); tick();
ok(G('paddle.x') === afterKey, 'no snap back to mouse after keyboard use');
ptr('pointermove', 100, 500); tick();
ok(G('paddle.x') === afterKey, 'motionless pointermove ignored');
ptr('pointermove', 600, 500); tick();
ok(Math.abs(G('paddle.x + paddle.w / 2') - 600) < 1e-9, 'mouse retakes control');
ok(G('canvas.style.cursor') === 'none', 'cursor hidden over playfield: ' + G('canvas.style.cursor'));
ptr('pointermove', pbx, pby); ok(G('canvas.style.cursor') === 'pointer', 'pointer cursor over button');
ptr('pointermove', 600, 500);

// --- full games on mouse autopilot
function run(maxSeconds, opts = {}) {
  let offset = 0, prevVy = 0;
  const log = [];
  for (let f = 0; f < maxSeconds * 60; f++) {
    const st = G('state');
    if (st === 'win' || st === 'gameover') return { st, t: f / 60, log };
    if (st === 'serve' && G('stateTime') > 0.3) ptr('pointerdown', G('paddle.x + paddle.w / 2'), 550);
    if (st === 'levelclear' && opts.clickLevelClear) {
      if (G('stateTime') < 0.5) {
        ptr('pointerdown', 400, 300);
        if (G('state') !== 'levelclear') log.push('EARLY CLICK ACCEPTED');
      } else if (G('stateTime') > 0.7) {
        ptr('pointerdown', 400, 300);
      }
    }
    if (st === 'playing') {
      const vy = G('ball.vy');
      if (vy > 0 && prevVy <= 0) offset = (Math.random() - 0.5) * 1.6 * (G('paddle.w') / 2);
      prevVy = vy;
      ptr('pointermove', opts.miss ? (G('ball.x') < 400 ? 760 : 40) : G('ball.x') - offset, 550);
    }
    tick();
    const after = G('state');
    if (after !== st) {
      log.push(`${(f / 60).toFixed(1)}s ${st}->${after} L${G('level') + 1} score=${G('score')} lives=${G('lives')} bricks=${G('bricks.length')}`);
    }
  }
  return { st: G('state'), t: maxSeconds, log };
}

let r = run(3600);
console.log(r.log.join('\n'));
ok(r.st === 'win', 'won the game on autopilot, state=' + r.st);
ok(texts.includes('YOU WIN!'), 'win screen');
ok(store['brick-breaker-best'] === String(G('score')), 'best saved ' + store['brick-breaker-best']);
const wonScore = G('score');
for (let i = 0; i < 300; i++) tick();
ok(G('particles.length') <= 270, 'confetti bounded ' + G('particles.length'));

key('keydown', 'Space');
ok(G('state') === 'serve' && G('lives') === 3 && G('score') === 0 && G('level') === 0 && G('bricks.length') === 72,
  'restart resets game');
r = run(600, { miss: true });
console.log(r.log.join('\n'));
ok(r.st === 'gameover' && G('lives') === 0, 'game over after 3 lost balls');
tick();
ok(texts.includes('GAME OVER'), 'game over screen');
key('keydown', 'Space'); ok(G('state') === 'gameover', 'restart blocked during first second');
for (let i = 0; i < 70; i++) tick();
ok(store['brick-breaker-best'] === String(wonScore), 'best kept');
key('keydown', 'Enter'); ok(G('state') === 'serve', 'Enter restarts after delay');

r = run(3600, { clickLevelClear: true });
console.log(r.log.join('\n'));
ok(r.st === 'win' && !r.log.includes('EARLY CLICK ACCEPTED'), 'second win with click-through');

const v = G('__v');
ok(v.length === 0, 'invariant violations: ' + v.slice(0, 5).join(' | ') + ' (' + v.length + ')');
ok(bad.length === 0, 'non-finite draw args: ' + bad.slice(0, 5).join(' | '));
ok(toneCount > 100, 'sounds played: ' + toneCount);

// --- resize with DPR 2 into a small window
sb.devicePixelRatio = 2; sb.innerWidth = 500; sb.innerHeight = 700; winL.fire('resize', {});
ok(G('canvas.width') === 968 && Math.abs(G('sx') - G('sy')) < 0.01,
  `resize dpr2 ${G('canvas.width')}x${G('canvas.height')} sx=${G('sx')} sy=${G('sy')}`);
console.log(`\n${passed} checks passed${process.exitCode ? ', SOME FAILED' : ''}`);

