1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Brick Breaker</title>
7	<style>
8	  html {
9	    height: 100%;
10	    background: #05060f;
11	  }
12	  body {
13	    margin: 0;
14	    height: 100%;
15	    overflow: hidden;
16	    display: flex;
17	    align-items: center;
18	    justify-content: center;
19	    background: radial-gradient(ellipse at center, #151c44 0%, #05060f 75%);
20	    user-select: none;
21	    -webkit-user-select: none;
22	  }
23	  canvas {
24	    display: block;
25	    border-radius: 10px;
26	    box-shadow: 0 0 0 2px #24306a, 0 12px 48px rgba(0, 0, 0, 0.7), 0 0 90px rgba(70, 110, 255, 0.18);
27	    touch-action: none;
28	  }
29	</style>
30	</head>
31	<body>
32	<canvas id="game" aria-label="Brick Breaker game"></canvas>
33	<script>
34	'use strict';
35	
36	// ===== Configuration ========================================================
37	const W = 800, H = 600;                 // logical playfield size
38	const HUD_H = 44;                       // height of the score bar
39	const TOP = HUD_H + 2;                  // top wall of the playfield
40	const MAX_LIVES = 3;
41	const LEVEL_BONUS = 1000;
42	const PADDLE_H = 14, PADDLE_Y = H - 40;
43	const PADDLE_SPEED = 760;               // keyboard paddle speed (px/s)
44	const BALL_R = 7;
45	const SPEED_STEP = 2.5;                 // ball speed gained per brick hit (px/s)
46	const MAX_BOUNCE = Math.PI / 3;         // steepest paddle bounce: 60° off vertical
47	const BEST_KEY = 'brick-breaker-best';
48	const FONT = "'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif";
49	const COLORS = ['#ff5c7a', '#ff9f43', '#ffd84d', '#5ee38b', '#4cc9f0', '#9b8cff'];
50	
51	// Layout codes: '.' = empty, '1'..'3' = hits needed to break the brick.
52	const LEVELS = [
53	  {
54	    speed: 360, maxSpeed: 560, paddle: 110,
55	    rowColors: [0, 1, 2, 3, 4, 5],
56	    layout: [
57	      '111111111111',
58	      '111111111111',
59	      '111111111111',
60	      '111111111111',
61	      '111111111111',
62	      '111111111111',
63	    ],
64	  },
65	  {
66	    speed: 420, maxSpeed: 640, paddle: 100,
67	    rowColors: [0, 1, 2, 3, 4, 3, 2, 1, 0],
68	    layout: [
69	      '....2222....',
70	      '...211112...',
71	      '..21111112..',
72	      '.2113333112.',
73	      '211333333112',
74	      '.2113333112.',
75	      '..21111112..',
76	      '...211112...',
77	      '....2222....',
78	    ],
79	  },
80	];
81	
82	// ===== Canvas & scaling =====================================================
83	const canvas = document.getElementById('game');
84	const ctx = canvas.getContext('2d');
85	let sx = 1, sy = 1;                     // logical units -> backing-store pixels
86	
87	function resize() {
88	  const dpr = window.devicePixelRatio || 1;
89	  const scale = Math.max(0.2, Math.min((window.innerWidth - 16) / W, (window.innerHeight - 16) / H));
90	  const cssW = Math.floor(W * scale), cssH = Math.floor(H * scale);
91	  canvas.style.width = cssW + 'px';
92	  canvas.style.height = cssH + 'px';
93	  canvas.width = Math.round(cssW * dpr);
94	  canvas.height = Math.round(cssH * dpr);
95	  sx = canvas.width / W;
96	  sy = canvas.height / H;
97	}
98	window.addEventListener('resize', resize);
99	resize();
100	
101	// ===== Game state ===========================================================
102	const paddle = { x: 0, y: PADDLE_Y, w: 110, h: PADDLE_H };
103	const ball = { x: W / 2, y: PADDLE_Y - BALL_R, vx: 0, vy: 0, r: BALL_R, speed: 0 };
104	let bricks = [], particles = [], floaters = [], trail = [];
105	let state = 'title';      // title | serve | playing | paused | levelclear | gameover | win
106	let stateTime = 0;        // seconds since the current state began
107	let pausedFrom = 'playing';
108	let score = 0, lives = MAX_LIVES, level = 0;
109	let best = loadBest(), newBest = false;
110	let levelIntro = false;   // show "LEVEL N" until the first launch of a level
111	let ballLost = false;     // show "lives left" until the next launch
112	let shake = 0;
113	let toastText = '', toastTime = 0;
114	
115	function setState(s) {
116	  state = s;
117	  stateTime = 0;
118	  updateCursor();
119	}
120	
121	function loadLevel(index) {
122	  const lvl = LEVELS[index];
123	  const rows = lvl.layout.length, cols = lvl.layout[0].length;
124	  const gap = 4, bh = 22;
125	  const bw = Math.floor((W - 40 - (cols - 1) * gap) / cols);
126	  const offX = Math.round((W - (cols * bw + (cols - 1) * gap)) / 2);
127	  const offY = TOP + 34;
128	  level = index;
129	  bricks = [];
130	  for (let r = 0; r < rows; r++) {
131	    for (let c = 0; c < cols; c++) {
132	      const hits = Number(lvl.layout[r][c]) || 0;
133	      if (hits > 0) {
134	        bricks.push({
135	          x: offX + c * (bw + gap), y: offY + r * (bh + gap), w: bw, h: bh,
136	          hits, maxHits: hits, color: COLORS[lvl.rowColors[r]], flash: 0,
137	        });
138	      }
139	    }
140	  }
141	  paddle.w = lvl.paddle;
142	  paddle.x = (W - paddle.w) / 2;
143	  particles = [];
144	  floaters = [];
145	  levelIntro = true;
146	  ballLost = false;
147	  resetBall();
148	}
149	
150	function resetBall() {
151	  ball.speed = LEVELS[level].speed;
152	  ball.vx = 0;
153	  ball.vy = 0;
154	  trail = [];
155	  stickBallToPaddle();
156	}
157	
158	function stickBallToPaddle() {
159	  ball.x = paddle.x + paddle.w / 2;
160	  ball.y = paddle.y - ball.r - 1;
161	}
162	
163	function newGame() {
164	  score = 0;
165	  lives = MAX_LIVES;
166	  newBest = false;
167	  loadLevel(0);
168	  setState('serve');
169	  sfx.start();
170	}
171	
172	function launchBall() {
173	  // Launch toward the held arrow key, otherwise to a random side.
174	  let dir = (keys.right ? 1 : 0) - (keys.left ? 1 : 0);
175	  if (dir === 0) dir = Math.random() < 0.5 ? -1 : 1;
176	  const angle = dir * (0.2 + Math.random() * 0.35);
177	  ball.vx = ball.speed * Math.sin(angle);
178	  ball.vy = -ball.speed * Math.cos(angle);
179	  levelIntro = false;
180	  ballLost = false;
181	  setState('playing');
182	  sfx.launch();
183	}
184	
185	function nextLevel() {
186	  loadLevel(level + 1);
187	  setState('serve');
188	}
189	
190	function togglePause() {
191	  if (state === 'paused') {
192	    setState(pausedFrom);
193	  } else if (state === 'serve' || state === 'playing') {
194	    pausedFrom = state;
195	    setState('paused');
196	  } else {
197	    return;
198	  }
199	  sfx.pause();
200	}
201	
202	// Space / Enter / click: whatever "continue" means in the current state.
203	function primaryAction() {
204	  switch (state) {
205	    case 'title': newGame(); break;
206	    case 'serve': launchBall(); break;
207	    case 'paused': togglePause(); break;
208	    case 'levelclear': if (stateTime > 0.6) nextLevel(); break;
209	    case 'gameover':
210	    case 'win': if (stateTime > 1) newGame(); break;
211	  }
212	}
213	
214	function levelComplete() {
215	  score += LEVEL_BONUS;
216	  if (level + 1 < LEVELS.length) {
217	    setState('levelclear');
218	    sfx.levelClear();
219	  } else {
220	    endGame(true);
221	  }
222	}
223	
224	function loseLife() {
225	  lives--;
226	  shake = 0.35;
227	  if (lives <= 0) {
228	    lives = 0;
229	    endGame(false);
230	  } else {
231	    sfx.lose();
232	    resetBall();
233	    ballLost = true;
234	    setState('serve');
235	  }
236	}
237	
238	function endGame(won) {
239	  if (score > best) {
240	    best = score;
241	    newBest = true;
242	    saveBest(best);
243	  }
244	  setState(won ? 'win' : 'gameover');
245	  if (won) sfx.win(); else sfx.gameOver();
246	}
