261	// ===== Physics ==============================================================
262	function movePaddle(dt) {
263	  const dir = (keys.right ? 1 : 0) - (keys.left ? 1 : 0);
264	  if (dir !== 0) {
265	    paddle.x += dir * PADDLE_SPEED * dt;
266	    pointerActive = false;
267	  } else if (pointerActive) {
268	    paddle.x = pointerX - paddle.w / 2;
269	  }
270	  paddle.x = Math.max(0, Math.min(W - paddle.w, paddle.x));
271	}
272	
273	function updateBall(dt) {
274	  // Sub-step so the ball never moves more than 4px at a time (no tunnelling).
275	  const steps = Math.max(1, Math.ceil((ball.speed * dt) / 4));
276	  const h = dt / steps;
277	  for (let i = 0; i < steps; i++) {
278	    if (!stepBall(h)) return;
279	  }
280	  trail.push({ x: ball.x, y: ball.y });
281	  if (trail.length > 10) trail.shift();
282	}
283	
284	// Moves the ball one sub-step. Returns false once the ball is lost or the level is cleared.
285	function stepBall(h) {
286	  const r = ball.r;
287	
288	  ball.x += ball.vx * h;
289	  if (ball.x < r) { ball.x = r; ball.vx = Math.abs(ball.vx); sfx.wall(); }
290	  else if (ball.x > W - r) { ball.x = W - r; ball.vx = -Math.abs(ball.vx); sfx.wall(); }
291	  collideBricks(true);
292	
293	  ball.y += ball.vy * h;
294	  if (ball.y < TOP + r) { ball.y = TOP + r; ball.vy = Math.abs(ball.vy); sfx.wall(); }
295	  collideBricks(false);
296	
297	  if (ball.vy > 0 &&
298	      ball.y + r >= paddle.y && ball.y <= paddle.y + paddle.h * 0.75 &&
299	      ball.x + r >= paddle.x && ball.x - r <= paddle.x + paddle.w) {
300	    bounceOffPaddle();
301	  }
302	
303	  if (ball.y - r > H) { loseLife(); return false; }
304	  if (bricks.length === 0) { levelComplete(); return false; }
305	  return true;
306	}
307	
308	// Resolves overlap with bricks along the axis that just moved. The ball was clear
309	// of every brick before this move, so pushing it back to the nearest touched edge
310	// leaves it clear again. Only the most-overlapped brick takes the hit.
311	function collideBricks(horizontal) {
312	  const r = ball.r;
313	  const l = ball.x - r, rt = ball.x + r, t = ball.y - r, btm = ball.y + r;
314	  const v = horizontal ? ball.vx : ball.vy;
315	  let target = null, most = 0, edge = v > 0 ? Infinity : -Infinity;
316	  for (const b of bricks) {
317	    if (rt <= b.x || l >= b.x + b.w || btm <= b.y || t >= b.y + b.h) continue;
318	    const overlap = (Math.min(rt, b.x + b.w) - Math.max(l, b.x)) *
319	                    (Math.min(btm, b.y + b.h) - Math.max(t, b.y));
320	    if (overlap > most) { most = overlap; target = b; }
321	    if (horizontal) edge = v > 0 ? Math.min(edge, b.x) : Math.max(edge, b.x + b.w);
322	    else edge = v > 0 ? Math.min(edge, b.y) : Math.max(edge, b.y + b.h);
323	  }
324	  if (!target) return;
325	  if (horizontal) { ball.x = v > 0 ? edge - r : edge + r; ball.vx = -ball.vx; }
326	  else { ball.y = v > 0 ? edge - r : edge + r; ball.vy = -ball.vy; }
327	  hitBrick(target);
328	}
329	
330	function hitBrick(b) {
331	  b.hits--;
332	  b.flash = 1;
333	  if (b.hits <= 0) {
334	    bricks.splice(bricks.indexOf(b), 1);
335	    const points = 50 * b.maxHits;
336	    score += points;
337	    burst(b.x + b.w / 2, b.y + b.h / 2, b.color, 16);
338	    floaters.push({ text: '+' + points, x: b.x + b.w / 2, y: b.y + b.h / 2, life: 0.9 });
339	    sfx.brick(b.y);
340	  } else {
341	    score += 10;
342	    burst(ball.x, ball.y, '#ffffff', 6);
343	    sfx.tough();
344	  }
345	  ball.speed = Math.min(LEVELS[level].maxSpeed, ball.speed + SPEED_STEP);
346	  const k = ball.speed / Math.hypot(ball.vx, ball.vy);
347	  ball.vx *= k;
348	  ball.vy *= k;
349	}
350	
351	// The further from the paddle centre the ball lands, the sharper it is deflected.
352	function bounceOffPaddle() {
353	  const rel = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2 + ball.r);
354	  const angle = Math.max(-1, Math.min(1, rel)) * MAX_BOUNCE;
355	  ball.vx = ball.speed * Math.sin(angle);
356	  ball.vy = -ball.speed * Math.cos(angle);
357	  ball.y = paddle.y - ball.r;
358	  sfx.paddle();
359	}
