361	// ===== Effects ==============================================================
362	function burst(x, y, color, count) {
363	  for (let i = 0; i < count; i++) {
364	    const a = Math.random() * Math.PI * 2;
365	    const s = 60 + Math.random() * 240;
366	    const life = 0.4 + Math.random() * 0.5;
367	    particles.push({
368	      x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s - 80, g: 600,
369	      life, maxLife: life, size: 2 + Math.random() * 3, color,
370	    });
371	  }
372	}
373	
374	function updateEffects(dt) {
375	  if (state === 'win' && particles.length < 260) {
376	    for (let i = Math.ceil(dt * 120); i > 0; i--) {
377	      const life = 3 + Math.random();
378	      particles.push({
379	        x: Math.random() * W, y: TOP, vx: (Math.random() - 0.5) * 100, vy: 30 + Math.random() * 90, g: 50,
380	        life, maxLife: life, size: 3 + Math.random() * 4,
381	        color: COLORS[Math.floor(Math.random() * COLORS.length)],
382	      });
383	    }
384	  }
385	  for (let i = particles.length - 1; i >= 0; i--) {
386	    const p = particles[i];
387	    p.life -= dt;
388	    if (p.life <= 0) { particles.splice(i, 1); continue; }
389	    p.vy += p.g * dt;
390	    p.x += p.vx * dt;
391	    p.y += p.vy * dt;
392	  }
393	  for (let i = floaters.length - 1; i >= 0; i--) {
394	    const f = floaters[i];
395	    f.life -= dt;
396	    if (f.life <= 0) { floaters.splice(i, 1); continue; }
397	    f.y -= 40 * dt;
398	  }
399	  for (const b of bricks) b.flash = Math.max(0, b.flash - dt * 5);
400	}
