402	// ===== Update ===============================================================
403	function update(dt) {
404	  stateTime += dt;
405	  toastTime = Math.max(0, toastTime - dt);
406	  if (state === 'paused') return;
407	  shake = Math.max(0, shake - dt);
408	  updateEffects(dt);
409	  if (state === 'serve' || state === 'playing') movePaddle(dt);
410	  if (state === 'serve') stickBallToPaddle();
411	  else if (state === 'playing') updateBall(dt);
412	  else if (state === 'levelclear' && stateTime > 3) nextLevel();
413	}
