491	function drawBricks() {
492	  for (const b of bricks) {
493	    roundRect(b.x, b.y, b.w, b.h, 4);
494	    if (b.hits >= 2) {
495	      // Armoured bricks: gold (3 hits left) and steel (2 hits left), one pip per hit.
496	      ctx.fillStyle = b.hits >= 3 ? '#f2c14e' : '#b8c4dc';
