498	      ctx.strokeStyle = b.hits >= 3 ? '#9c6f12' : '#5f6c8a';
499	      ctx.lineWidth = 2;
500	      ctx.stroke();
501	    } else {
502	      ctx.fillStyle = b.color;
503	      ctx.fill();
504	    }
505	    ctx.fillStyle = 'rgba(255, 255, 255, 0.35)';
506	    ctx.fillRect(b.x + 4, b.y + 3, b.w - 8, 3);
507	    ctx.fillStyle = 'rgba(0, 0, 0, 0.22)';
508	    ctx.fillRect(b.x + 4, b.y + b.h - 5, b.w - 8, 2);
509	    if (b.hits >= 2) {
