511	      for (let i = 0; i < b.hits; i++) {
512	        ctx.beginPath();
513	        ctx.arc(b.x + b.w / 2 + (i - (b.hits - 1) / 2) * 10, b.y + b.h / 2 + 1, 2.6, 0, Math.PI * 2);
514	        ctx.fill();
