const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('index.html', 'utf8');
const code = html.match(/<script>([\s\S]*?)<\/script>/)[1];

function makeListeners() { const map = {}; return { map, add(t, fn) { (map[t] ||= []).push(fn); }, fire(t, ev) { for (const fn of map[t] || []) fn(ev); } }; }
const winL = makeListeners(), docL = makeListeners(), canL = makeListeners();
const texts = []; const bad = [];
function checkNum(name, args) { for (const a of args) if (typeof a === 'number' && !Number.isFinite(a)) bad.push(name + ':' + args.join(',')); }
const target = {
  measureText: (s) => ({ width: String(s).length * 8 }),
  createLinearGradient: (...a) => { checkNum('grad', a); return { addColorStop() {} }; },
  fillText: (s, x, y) => { texts.push(String(s)); checkNum('fillText', [x, y]); },
  strokeText: (s, x, y) => checkNum('strokeText', [x, y]),
};
const ctx2d = new Proxy(target, {
  get(t, k) { return k in t ? t[k] : (...args) => checkNum(String(k), args); },
  set(t, k, v) { if (typeof v === 'number' && !Number.isFinite(v)) bad.push('set ' + String(k)); t[k] = v; return true; },
});
const canvas = { width: 300, height: 150, style: {}, getContext: () => ctx2d,
  getBoundingClientRect: () => ({ left: 0, top: 0, width: 800, height: 600 }), addEventListener: (t, f) => canL.add(t, f) };
const store = {};
let toneCount = 0;
class P { setValueAtTime() {} exponentialRampToValueAtTime(v) { if (!(v > 0)) throw new Error('bad ramp ' + v); } }
class N { constructor() { this.frequency = new P(); this.gain = new P(); } connect(n) { return n; } start() {} stop() {} }
class AC { constructor() { this.state = 'running'; this.currentTime = 0; this.destination = {}; } createOscillator() { toneCount++; return new N(); } createGain() { return new N(); } resume() { return Promise.resolve(); } }
let rafCb = null;
const sb = {
  document: { getElementById: () => canvas, addEventListener: (t, f) => docL.add(t, f), hidden: false },
  localStorage: { getItem: k => (k in store ? store[k] : null), setItem: (k, v) => { store[k] = String(v); } },
  requestAnimationFrame: (cb) => { rafCb = cb; return 1; },
  innerWidth: 1024, innerHeight: 768, devicePixelRatio: 1, AudioContext: AC,
  addEventListener: (t, f) => winL.add(t, f),
};
sb.window = sb;
vm.createContext(sb);
vm.runInContext(code, sb, { filename: 'game.js' });
const G = (e) => vm.runInContext(e, sb);
let now = 1000;
function tick(ms = 1000 / 60) { now += ms; const cb = rafCb; rafCb = null; texts.length = 0; cb(now); }
function key(type, code, extra = {}) { winL.fire(type, { code, repeat: false, ctrlKey: false, metaKey: false, altKey: false, preventDefault() {}, ...extra }); }
function ptr(type, x, y, extra = {}) { const ev = { clientX: x, clientY: y, pointerType: 'mouse', button: 0, ...extra }; (type === 'pointerdown' ? canL : winL).fire(type, ev); }
let passed = 0;
function ok(c, msg) { if (!c) { console.log('FAIL:', msg); process.exitCode = 1; } else passed++; }

// per-substep invariants
vm.runInContext(`
  var __v = []; var __orig = stepBall;
  stepBall = function (h) {
    const res = __orig(h);
    if (state === 'playing') {
      const r = ball.r, e = 1e-6;
      if (ball.x < r - e || ball.x > W - r + e) __v.push('x out ' + ball.x);
      if (ball.y < TOP + r - e) __v.push('above top ' + ball.y);
      for (const b of bricks) if (ball.x + r > b.x + e && ball.x - r < b.x + b.w - e && ball.y + r > b.y + e && ball.y - r < b.y + b.h - e) { __v.push('overlap ' + b.x + ',' + b.y + ' ball ' + ball.x + ',' + ball.y); break; }
      const sp = Math.hypot(ball.vx, ball.vy);
      if (Math.abs(sp - ball.speed) > 1e-6 * ball.speed) __v.push('speed mismatch');
      if (Math.abs(ball.vy) < 0.45 * ball.speed) __v.push('too flat ' + ball.vy);
      if (ball.speed > LEVELS[level].maxSpeed + 1e-9) __v.push('too fast');
    }
    return res;
  };`, sb);

// --- title
tick(); tick();
ok(G('state') === 'title', 'title state');
ok(texts.includes('BRICK BREAKER'), 'title drawn');
ok(G('bricks.length') === 72, 'level 1 has 72 bricks');
ok(texts.includes('SCORE') && texts.includes('LEVEL') && texts.includes('LIVES') && texts.includes('0') && texts.includes('1 / 2'), 'HUD drawn: ' + texts.join('|'));
ok(G('canvas.style.width') === '1002px' && G('canvas.style.height') === '751px', 'css size ' + G('canvas.style.width') + ' ' + G('canvas.style.height'));

